// @vitest-environment node
/**
 * P1.10 acceptance: the starter kit and the ABAP lab-guide samples run
 * UNCHANGED against every supported release, on both paths.
 *
 * WHAT RUNS. The two consumers the repo ships, as a caller would run them:
 *
 *   - The starter kit, generated by the shipped generator (lib/studio/
 *     scaffold.ts, what Studio's download serves): `demo.mjs`, run by Node in
 *     a child process, and `client.ts`, transpiled and called from another.
 *     `COREEDGE_BASE_URL`, the one variable the kit documents, points at
 *     `/api/northbound` and then `/api/northbound/v1`.
 *   - The calls in docs/coreedge-abap-lab-guide.md: the curl calls of
 *     exercise 1, the two ABAP read outlines and the create outline of
 *     section 6.2, and Appendix A — PARSED FROM THE GUIDE, so a sample edited
 *     into something the API does not serve fails here, and a sample this
 *     parser no longer finds fails the count checks. ABAP cannot run in CI;
 *     the HTTP requests it would send can, and are sent.
 *
 * WHERE THEY RUN. A local HTTP server in front of the real edge middleware and
 * the real routes, on real PostgreSQL (tests/helpers/northbound-world.ts),
 * with SAP stood in by an OData stub. Each consumer runs unpinned and then
 * pinned to every supported version: the server adds `CoreEdge-Version` to
 * what the kit sends, as a caller adopting pinning would, so the kit's own
 * code stays byte for byte what developers downloaded.
 *
 * Opt-in like the other integration suites: skipped without TEST_DATABASE_URL.
 */

import { execFile } from "node:child_process";
import { randomBytes, randomUUID } from "node:crypto";
import { readFileSync } from "node:fs";
import { mkdtemp, rm, writeFile } from "node:fs/promises";
import { createServer, type IncomingMessage, type Server } from "node:http";
import type { AddressInfo } from "node:net";
import { tmpdir } from "node:os";
import path from "node:path";
import { promisify } from "node:util";

import { NextRequest } from "next/server";
import ts from "typescript";
import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/db/prisma", async () => {
  const { PrismaClient } = await import("@prisma/client");
  const { tenantScopeGuard } = await import("@/lib/db/tenant-guard");
  const base = new PrismaClient({
    datasourceUrl: process.env.TEST_DATABASE_URL ?? "postgresql://unused:unused@localhost:1/unused",
  });
  return { prisma: base.$extends(tenantScopeGuard()) };
});

import { prisma } from "@/lib/db/prisma";
import { buildScaffold } from "@/lib/studio/scaffold";
import { supportedVersions, VERSION_HEADER } from "@/lib/northbound/version-policy";
import {
  removeWorld,
  sapStub,
  seedApp,
  seedWorld,
  serveNorthbound,
  type Envelope,
  type NorthboundApp,
  type NorthboundWorld,
} from "../helpers/northbound-world";

const run = promisify(execFile);
const RUN = `p110r-${randomUUID().slice(0, 8)}`;
const BASES = ["/api/northbound", "/api/northbound/v1"] as const;
const SUPPORTED = supportedVersions(new Date()).map((v) => v.version);
const DEFAULT = SUPPORTED[0]!;
const MATRIX = BASES.flatMap((base) => [null, ...SUPPORTED].map((pin) => [base, pin] as const));

const realFetch = globalThis.fetch;
const sap = sapStub(realFetch);
let world: NorthboundWorld;
let app: NorthboundApp;
let server: Server;
let origin = "";
/** What the local server adds to every request: the version a pass pins. */
let pinning: string | null = null;

/* ── the local deployment ─────────────────────────────────────────────── */

async function readBody(req: IncomingMessage): Promise<Buffer> {
  const chunks: Buffer[] = [];
  for await (const chunk of req) chunks.push(chunk as Buffer);
  return Buffer.concat(chunks);
}

function startServer(): Promise<void> {
  server = createServer((req, res) => {
    void (async () => {
      const headers = new Headers();
      for (const [name, value] of Object.entries(req.headers)) {
        if (typeof value === "string") headers.set(name, value);
        else if (Array.isArray(value)) headers.set(name, value.join(", "));
      }
      // Every request arrives from one address; its edge buckets are this suite's.
      headers.set("x-real-ip", "203.0.113.150");
      if (pinning) headers.set(VERSION_HEADER, pinning);
      const body = req.method === "GET" || req.method === "HEAD" ? null : (await readBody(req)).toString("utf8");
      const response = await serveNorthbound(
        new NextRequest(new URL(req.url ?? "/", origin), { method: req.method ?? "GET", headers, body }),
      );
      res.writeHead(response.status, Object.fromEntries(response.headers.entries()));
      res.end(Buffer.from(await response.arrayBuffer()));
    })().catch((err: unknown) => {
      res.writeHead(500, { "content-type": "text/plain" });
      res.end(String(err));
    });
  });
  return new Promise((resolve) => {
    server.listen(0, "127.0.0.1", () => {
      origin = `http://127.0.0.1:${(server.address() as AddressInfo).port}`;
      resolve();
    });
  });
}

/* ── the starter kit ──────────────────────────────────────────────────── */

let kitDir = "";

/** The kit exactly as Studio's download generates it for this interface. */
async function writeKit(dir: string, baseUrl: string): Promise<void> {
  const iface = await prisma.interface.findFirstOrThrow({
    where: { organizationId: world.organizationId, id: app.readInterfaceId },
    select: { id: true, name: true, externalId: true, sapProduct: true, operation: true, entitySet: true, version: true, responseSchema: true },
  });
  for (const file of buildScaffold({ ...iface, solutionName: "Travel portal" }, baseUrl, [])) {
    await writeFile(path.join(dir, file.path), file.contents, "utf8");
  }
  // client.ts is TypeScript; a developer's toolchain compiles it. So does this.
  const client = readFileSync(path.join(dir, "client.ts"), "utf8");
  const js = ts.transpileModule(client, {
    compilerOptions: { module: ts.ModuleKind.ESNext, target: ts.ScriptTarget.ES2022 },
  }).outputText;
  await writeFile(path.join(dir, "client.mjs"), js, "utf8");
  await writeFile(
    path.join(dir, "use-client.mjs"),
    `import { createClient } from "./client.mjs";
const client = createClient({ baseUrl: process.env.COREEDGE_BASE_URL, token: process.env.COREEDGE_TOKEN });
console.log(JSON.stringify(await client.read(5)));
`,
    "utf8",
  );
}

/** Node, in the kit's directory, with only the two variables the kit documents. */
function node(dir: string, script: string, baseUrl: string) {
  return run(process.execPath, [script], {
    cwd: dir,
    env: {
      // As a deployed application runs it.
      NODE_ENV: "production",
      PATH: process.env.PATH ?? "",
      COREEDGE_BASE_URL: baseUrl,
      COREEDGE_TOKEN: app.token,
      NO_PROXY: "127.0.0.1,localhost",
    },
    timeout: 30_000,
  });
}

/* ── the ABAP lab guide's samples, read from the guide ───────────────── */

interface Sample {
  /** Where in the guide it came from. */
  source: string;
  method: "GET" | "POST";
  /** The path after the base, as the sample sends it ("/interfaces/{id}/data?limit=50"). */
  path: string;
  headers: Record<string, string>;
  body?: unknown;
}

const GUIDE = readFileSync(path.join(process.cwd(), "docs/coreedge-abap-lab-guide.md"), "utf8");
/** The prefix the guide tells Basis to put in SM59, and the one its curl calls use. */
const DOC_BASE = "/api/northbound";

function between(start: string, end: string): string {
  const from = GUIDE.indexOf(start);
  const to = GUIDE.indexOf(end, from);
  expect(from, `the lab guide lost "${start}"`).toBeGreaterThan(-1);
  expect(to, `the lab guide lost "${end}"`).toBeGreaterThan(from);
  return GUIDE.slice(from, to);
}

/** Every placeholder the samples use, filled with this run's values. */
function fill(raw: string, values: { id: string; key: string }): string {
  return raw
    .replace(/\{ lv_iface_id \}|<id>|\{id\}/g, values.id)
    .replace(/\{ lv_token \}|\$CE_TOKEN|<ce_ token>/g, app.token)
    .replace(/<cew_ key>/g, app.writeKey)
    .replace(/<key>/g, values.key);
}

function guideSamples(): { reads: Sample[]; create: Sample; appendix: { method: string; path: string }[] } {
  const section62 = between("### 6.2 ABAP as consumer", "### 6.3 ");
  expect(section62).toMatch(/path prefix\s+`\/api\/northbound`/);

  // The two read outlines (ABAP Cloud and classic): their path and headers.
  const abapBlocks = [...section62.matchAll(/```abap\n([\s\S]*?)```/g)].map((m) => m[1]!);
  expect(abapBlocks).toHaveLength(2);
  const reads: Sample[] = abapBlocks.map((block, i) => {
    const uri = /(?:i_uri_path|uri)\s*=\s*\|([^|]+)\|/.exec(block)?.[1];
    expect(uri, `ABAP read outline ${i + 1} has no request path`).toBeTruthy();
    expect(block).toMatch(/if_web_http_client=>get|co_request_method_get/);
    const headers = Object.fromEntries(
      [...block.matchAll(/set_header_field\(\s*(?:i_)?name\s*=\s*'([^']+)'\s+(?:i_)?value\s*=\s*(?:\|([^|]*)\||'([^']*)')/g)].map(
        (m) => [m[1]!, m[2] ?? m[3] ?? ""],
      ),
    );
    expect(Object.keys(headers).sort()).toEqual(["Accept", "Authorization"]);
    return { source: `section 6.2, ABAP read outline ${i + 1}`, method: "GET", path: uri!, headers };
  });

  // The create outline: path, method, headers and body shape from its bullets.
  const create = between("**Create: OUTLINE.**", "**Payload format.**");
  const pathMatch = /\*\*Path:\*\* `([^`]+)`, method (\w+)/.exec(create);
  expect(pathMatch).not.toBeNull();
  const createHeaders = Object.fromEntries(
    [...create.matchAll(/^\s+- `([A-Za-z-]+): ([^`]+)`/gm)].map((m) => [m[1]!, m[2]!]),
  );
  expect(Object.keys(createHeaders).sort()).toEqual(["Authorization", "Content-Type", "Idempotency-Key", "X-CoreEdge-Write-Key"]);
  expect(create).toContain('`{"record": { ...fields of the entity... }}`');

  // Appendix A: every route the reference lists.
  const appendix = [...between("## Appendix A", "## Appendix B").matchAll(/^\| `(GET|POST) (\/api\/northbound[^`]*)` \|/gm)].map(
    (m) => ({ method: m[1]!, path: m[2]! }),
  );
  expect(appendix).toHaveLength(4);

  return {
    reads,
    create: {
      source: "section 6.2, create outline",
      method: pathMatch![2] as "POST",
      path: pathMatch![1]!,
      headers: createHeaders,
      body: { record: { Description: "From the ABAP create outline" } },
    },
    appendix,
  };
}

/** Exercise 1's curl calls, against the lab host the guide names. */
function curlSamples(): Sample[] {
  const exercise = between("### Exercise 1:", "### Exercise 2:");
  const calls = [...exercise.matchAll(/curl -sS -H "Authorization: Bearer \$CE_TOKEN" "?https:\/\/coreedge-lab\.example\.com(\/api\/northbound[^"\s]*)"?/g)];
  expect(calls).toHaveLength(2);
  return calls.map((m, i) => ({
    source: `exercise 1, curl call ${i + 1}`,
    method: "GET",
    path: m[1]!.slice(DOC_BASE.length),
    headers: { Authorization: "Bearer $CE_TOKEN" },
  }));
}

async function replay(sample: Sample, base: string, pin: string | null, key: string, body?: unknown) {
  const values = { id: sample.method === "POST" ? app.writeInterfaceId : app.readInterfaceId, key };
  const headers = Object.fromEntries(Object.entries(sample.headers).map(([k, v]) => [k, fill(v, values)]));
  if (pin) headers[VERSION_HEADER] = pin;
  const res = await realFetch(`${origin}${base}${fill(sample.path, values)}`, {
    method: sample.method,
    headers,
    body: sample.method === "POST" ? JSON.stringify(body ?? sample.body) : null,
  });
  const text = await res.text();
  return { res, status: res.status, json: (text ? JSON.parse(text) : null) as Envelope };
}

/* ── the suite ────────────────────────────────────────────────────────── */

describe.skipIf(!process.env.TEST_DATABASE_URL)("consumers run unchanged on every path and supported version (P1.10)", () => {
  beforeAll(async () => {
    vi.stubEnv("SAP_CONNECTION_ENCRYPTION_KEY", randomBytes(32).toString("hex"));
    vi.stubGlobal("fetch", sap.fetch);
    world = await seedWorld(RUN);
    app = await seedApp(world, "Travel portal", { tokenPrefix: "ce_test_", expiresAt: new Date(Date.now() + 30 * 86_400_000) });
    await startServer();
    kitDir = await mkdtemp(path.join(tmpdir(), "coreedge-kit-"));
  });

  afterAll(async () => {
    pinning = null;
    await new Promise<void>((resolve) => (server ? server.close(() => resolve()) : resolve()));
    if (kitDir) await rm(kitDir, { recursive: true, force: true });
    vi.unstubAllGlobals();
    vi.unstubAllEnvs();
    if (world) await removeWorld(world);
  });

  describe.each(MATRIX)("starter kit on %s, pinned to %s", (base, pin) => {
    it("npm run demo (node demo.mjs) reads the records", async () => {
      pinning = pin;
      const dir = await mkdtemp(path.join(kitDir, "demo-"));
      await writeKit(dir, `${origin}${base}`);
      const { stdout } = await node(dir, "demo.mjs", `${origin}${base}`);
      expect(stdout).toContain("2 record(s):");
      expect(stdout).toContain('"TravelID":"1"');
      expect(stdout).toContain("note:");
    });

    it("the generated typed client reads the records, not a draft, not empty", async () => {
      pinning = pin;
      const dir = await mkdtemp(path.join(kitDir, "client-"));
      await writeKit(dir, `${origin}${base}`);
      const { stdout } = await node(dir, "use-client.mjs", `${origin}${base}`);
      const result = JSON.parse(stdout) as { records: unknown[]; count: number; empty: boolean; draft: boolean; interface: { id: string } };
      expect(result).toMatchObject({ count: 2, empty: false, draft: false, interface: { id: app.readInterfaceId } });
      expect(result.records).toHaveLength(2);
    });
  });

  describe.each(MATRIX)("ABAP lab-guide samples on %s, pinned to %s", (base, pin) => {
    const served = pin ?? DEFAULT;
    const samples = guideSamples();

    it.each([...curlSamples(), ...samples.reads].map((s) => [s.source, s] as const))("%s answers as the guide says", async (_, sample) => {
      pinning = null;
      const { res, status, json } = await replay(sample, base, pin, "-");
      expect(status).toBe(200);
      expect(res.headers.get("x-correlation-id")).toMatch(/^[0-9a-f-]{36}$/);
      expect(res.headers.get(VERSION_HEADER)).toBe(served);
      if (sample.path === "/interfaces") {
        expect(json.data.interfaces.find((i: { id: string }) => i.id === app.readInterfaceId)).toMatchObject({ callable: true });
        return;
      }
      // The 200 body the outline's comment documents.
      expect(json.data).toEqual({
        records: expect.any(Array),
        count: 2,
        empty: false,
        interface: { id: app.readInterfaceId, name: expect.any(String), version: 1 },
        note: expect.any(String),
      });
    });

    it("the create outline: 201, the same key replays, a different payload under it is 409 (exercise 3)", async () => {
      pinning = null;
      const key = `abap-${randomUUID().replace(/-/g, "")}`;
      const first = await replay(samples.create, base, pin, key);
      expect(first.status).toBe(201);
      expect(first.json.data).toMatchObject({ created: true, record: expect.any(Object), location: expect.any(String) });
      expect(first.res.headers.get(VERSION_HEADER)).toBe(served);
      const again = await replay(samples.create, base, pin, key);
      expect(again.status).toBe(201);
      expect(again.res.headers.get("idempotency-replayed")).toBe("true");
      const changed = await replay(samples.create, base, pin, key, { record: { Description: "A different intent" } });
      expect(changed.status).toBe(409);
      expect(changed.json.error.code).toBe("CONFLICT");
    });

    it("every Appendix A route answers on this path", async () => {
      pinning = null;
      for (const route of samples.appendix) {
        const rel = route.path.slice(DOC_BASE.length).replace("?limit=N", "?limit=5");
        const sample: Sample =
          route.method === "POST"
            ? { ...samples.create, path: rel, source: "Appendix A" }
            : { source: "Appendix A", method: "GET", path: rel, headers: { Authorization: "Bearer $CE_TOKEN" } };
        const { status, res } = await replay(sample, base, pin, `appx-${randomUUID()}`);
        expect([200, 201], `${route.method} ${route.path}`).toContain(status);
        expect(res.headers.get(VERSION_HEADER)).toBe(served);
      }
    });

    it("exercise 1: the same call with a wrong token is 401 UNAUTHENTICATED", async () => {
      pinning = null;
      const res = await realFetch(`${origin}${base}/interfaces/${app.readInterfaceId}/data?limit=5`, {
        headers: { Authorization: "Bearer ce_wrong_token_for_the_lab", ...(pin ? { [VERSION_HEADER]: pin } : {}) },
      });
      expect(res.status).toBe(401);
      expect(((await res.json()) as { error: { code: string } }).error.code).toBe("UNAUTHENTICATED");
    });
  });
});
